APG_SOURCE = '// ============================================================================\n// Healthcare Platform — APG Capability Composition Example\n//\n// Composability pattern: Layered + Pipeline\n//   patient_management is the hub; all clinical capabilities depend on it\n//   emr -> pharmacy -> lab forms a clinical pipeline\n//   telemedicine is a separate channel feeding the same EMR\n//\n// Copyright (c) 2025 Datacraft — Nyimbi Odero\n// ============================================================================\n\nmodule healthcare_platform version 1.0.0 {\n    description: "Clinical information system — EMR, Pharmacy, Lab, Telemedicine";\n    author: "Datacraft";\n}\n\ntable Patient {\n    patient_id: str;\n    mrn: str;           // medical record number\n    first_name: str;\n    last_name: str;\n    date_of_birth: datetime;\n    gender: str;\n    national_id: str;\n    phone: str;\n    blood_group: str?;\n    allergies: List[str];\n    active: bool;\n}\n\ntable Encounter {\n    encounter_id: str;\n    patient_id: str;\n    encounter_type: str;   // outpatient | inpatient | emergency | telemedicine\n    facility_id: str;\n    attending_clinician: str;\n    admission_date: datetime;\n    discharge_date: datetime?;\n    primary_diagnosis: str?;  // ICD-10 code\n    status: str;              // active | closed | cancelled\n}\n\ntable Prescription {\n    prescription_id: str;\n    encounter_id: str;\n    patient_id: str;\n    drug_name: str;\n    dose: str;\n    frequency: str;\n    duration_days: int;\n    route: str;\n    prescriber_id: str;\n    status: str;  // active | dispensed | cancelled | completed\n}\n\ntable LabOrder {\n    order_id: str;\n    encounter_id: str;\n    patient_id: str;\n    test_name: str;\n    test_code: str;\n    priority: str;   // routine | urgent | stat\n    ordered_by: str;\n    ordered_at: datetime;\n    status: str;     // ordered | collected | processing | resulted | verified\n}\n\ncapability ClinicalCore {\n    contract: {\n        id: healthcare_platform_core,\n        provides: [\n            patient_registration_workflow,\n            clinical_encounter_lifecycle,\n            medication_management,\n            laboratory_workflow,\n            telemedicine_consultation,\n            clinical_decision_support\n        ],\n        requires: [auth, audl, ntfy, wflo, schd],\n        configuration: {\n            tenant_id: "default",\n            facility_name: "APG Health Centre",\n            ehr_standard: "HL7_FHIR_R4",\n            enable_clinical_decision_support: true,\n            controlled_substance_register: true,\n            consent_required_for_treatment: true,\n            hipaa_mode: true,\n            max_prescription_days: 90,\n            critical_lab_alert_minutes: 30\n        },\n        rule_engine: {\n            type: deterministic,\n            default_decision: allow,\n            rules: [\n                {name: "consent_required",\n                 when: "operation == treat and consent_recorded != true",\n                 action: deny},\n                {name: "drug_allergy_check",\n                 when: "allergy_detected == true and override_reason missing",\n                 action: deny},\n                {name: "controlled_substance_limit",\n                 when: "drug_schedule == II and quantity_gt == 30",\n                 action: deny},\n                {name: "prescriber_must_be_licensed",\n                 when: "prescriber_licensed != true",\n                 action: deny},\n                {name: "critical_lab_requires_immediate_notify",\n                 when: "lab_value_critical == true and clinician_notified != true",\n                 action: require_review},\n                {name: "minor_patient_requires_guardian_consent",\n                 when: "patient_age_lt == 18 and guardian_consent missing",\n                 action: require_review},\n                {name: "mental_health_enhanced_privacy",\n                 when: "diagnosis_category == mental_health and access_level_lt == treating_clinician",\n                 action: deny}\n            ]\n        },\n        ui: {shell: python, routes: [\n            {name: "Clinical Dashboard", path: "/clinical",            component: "ClinicalDashboard",  permission: "clinical:view",       nav_group: "Overview"},\n            {name: "Patient Registry",   path: "/clinical/patients",   component: "PatientRegistry",    permission: "clinical:patients",   nav_group: "Patients"},\n            {name: "Encounters",         path: "/clinical/encounters", component: "EncounterList",      permission: "clinical:encounters", nav_group: "Clinical"},\n            {name: "Prescriptions",      path: "/clinical/pharmacy",   component: "PharmacyWorkbench",  permission: "clinical:pharmacy",   nav_group: "Clinical"},\n            {name: "Laboratory",         path: "/clinical/lab",        component: "LabWorkbench",       permission: "clinical:lab",        nav_group: "Clinical"},\n            {name: "Telemedicine",       path: "/clinical/tele",       component: "TeleConsole",        permission: "clinical:tele",       nav_group: "Channels"},\n            {name: "Reports",            path: "/clinical/reports",    component: "ClinicalReports",    permission: "clinical:reports",    nav_group: "Analytics"}\n        ]},\n        theme: {name: clinical_theme, tokens: {\n            "color.primary":   "#006064",\n            "color.accent":    "#00838F",\n            "color.success":   "#2E7D32",\n            "color.warning":   "#E65100",\n            "color.danger":    "#C62828",\n            "surface.canvas":  "#F0F7F7",\n            "surface.panel":   "#FFFFFF",\n            "text.primary":    "#004D40",\n            "text.secondary":  "#607D8B",\n            "border.radius":   "6px",\n            "density":         "comfortable"\n        }, components: {\n            patients:     {icon: "user-heart",   status_indicator: "patient-status-chip"},\n            encounters:   {icon: "stethoscope",  status_indicator: "encounter-type-chip"},\n            prescriptions:{icon: "pill",         status_indicator: "rx-status-chip"},\n            lab_orders:   {icon: "flask",        status_indicator: "lab-priority-chip"}\n        }}\n    };\n    streaming: {\n        processor: bytewax,\n        stream: "apg.clinical.lifecycle",\n        key: "tenant_id",\n        events: [\n            "patient_registered", "encounter_opened", "encounter_closed",\n            "prescription_created", "medication_dispensed", "adverse_event_reported",\n            "lab_ordered", "specimen_collected", "result_verified", "critical_value_alerted",\n            "teleconsult_booked", "teleconsult_completed", "consent_recorded"\n        ],\n        guardrails: [\n            "no_treatment_without_consent",\n            "drug_allergy_check_enforced",\n            "controlled_substance_quantity_limit",\n            "critical_lab_immediate_notification",\n            "mental_health_enhanced_privacy"\n        ]\n    };\n    i18n: {supported_languages: [en, sw], default_language: en, fallback_language: en};\n}\n\nworkflow PatientAdmission {\n    steps: str = "registration -> triage -> assigned_to_clinician -> assessment -> treatment_plan -> active_treatment -> discharge_planning -> discharged";\n    human_tasks: [triage, treatment_plan, discharge_planning];\n    assignments: {triage: triage_nurse, treatment_plan: attending_doctor, discharge_planning: care_coordinator};\n    guards: {\n        treatment_plan: "consent_obtained and allergies_checked",\n        discharged: "discharge_summary_complete and follow_up_scheduled"\n    };\n}\n\nworkflow PrescriptionLifecycle {\n    steps: str = "prescribed -> drug_interaction_checked -> dispensed -> administered -> completed";\n    human_tasks: [drug_interaction_checked, dispensed];\n    assignments: {drug_interaction_checked: pharmacist, dispensed: pharmacist};\n    guards: {\n        dispensed: "interaction_check_passed and allergy_check_passed and consent_valid",\n        administered: "patient_identified and dose_confirmed"\n    };\n}\n\nagent ClinicalAssistant {\n    role: "clinical decision support";\n    model: "openai:gpt-4.1-mini";\n    system: "You are a clinical decision support system. Provide evidence-based recommendations, drug interaction checks, and diagnostic support. Always recommend clinician review. Cite clinical guidelines (WHO, NICE, Kenya Clinical Guidelines).";\n    capabilities: [clinical_decision_support, medication_management];\n    tools: [drug_database, icd10_lookup, lab_reference_ranges, clinical_guidelines];\n    memory: vector clinical_memory;\n    configuration: {temperature: 0.0, max_turns: 4};\n    rules: [\n        {name: "no_direct_prescribing", when: "action == prescribe", action: deny},\n        {name: "flag_paediatric_dosing", when: "patient_age_lt == 12", action: require_review}\n    ];\n}\n\napp HealthcarePlatform {\n    description: "Clinical information system composed from APG capabilities";\n    capabilities: [ClinicalCore];\n    agents: [ClinicalAssistant];\n    routes: ["/clinical", "/clinical/patients", "/clinical/pharmacy", "/clinical/lab"];\n    theme: {name: healthcare_platform_theme, tokens: {"accent": "#00838F", "border.radius": "6px"}};\n    runtime: {target: python, deployment: container, streaming: {processor: bytewax}};\n    deployments: {default: local, container: docker};\n}\n'
